import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { ContentService, PortfolioData } from '../../services/content.service';

@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [CommonModule, RouterLink, RouterLinkActive],
  templateUrl: './navbar.component.html'
})
export class NavbarComponent implements OnInit {
  content!: PortfolioData;
  isMobileMenuOpen: boolean = false;

  constructor(private contentService: ContentService) {}

  ngOnInit(): void {
    this.contentService.content$.subscribe(data => {
      this.content = data;
    });
  }
}
<header class="navbar">
  <div class="navbar-brand">
    <div class="brand-icon" routerLink="/admin" style="cursor: pointer;" title="Admin Dashboard Sign In">A</div>
    <div routerLink="/" style="cursor: pointer;">
      <div class="brand-title">{{ content.personalInfo.name || 'Amit Kumar Maurya' }}</div>
      <div class="brand-subtitle">{{ content.personalInfo.subtitle || 'Full Stack Developer | Angular & ASP.NET Core' }}</div>
    </div>
  </div>

  <nav class="nav-links">
    <a routerLink="/" routerLinkActive="active" [routerLinkActiveOptions]="{exact: true}">Home</a>
    <a routerLink="/projects" routerLinkActive="active">Projects</a>
    <a routerLink="/experience" routerLinkActive="active">Experience</a>
    <a routerLink="/skills" routerLinkActive="active">Skills Matrix</a>
    <a routerLink="/contact" routerLinkActive="active">Contact</a>
  </nav>

  <div class="navbar-actions">
    <a [href]="content.personalInfo?.github || 'https://github.com/amiitmaurya'" target="_blank" rel="noopener noreferrer" class="nav-icon-btn" title="GitHub Profile">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4"></path>
        <path d="M9 18c-4.51 2-5-2-7-2"></path>
      </svg>
    </a>

    <a [href]="content.personalInfo?.linkedin || 'https://linkedin.com/in/amit-mauryaa'" target="_blank" rel="noopener noreferrer" class="nav-icon-btn" title="LinkedIn Profile">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z"></path>
        <rect x="2" y="9" width="4" height="12"></rect>
        <circle cx="4" cy="4" r="2"></circle>
      </svg>
    </a>

    <a routerLink="/contact" class="btn btn-primary" style="padding: 8px 16px; font-size: 0.85rem;">
      Hire Me
    </a>
  </div>
</header>
